if (aFolder.isServer) {
  this._showServer();
  return;
}

const typeForTelemetry =
  [
    "Inbox",
    "Drafts",
    "Trash",
    "SentMail",
    "Templates",
    "Junk",
    "Archive",
    "Queue",
    "Virtual",
  ].find(x => aFolder.getFlag(Ci.nsMsgFolderFlags[x])) || "Other";
Glean.mail.folderOpened[typeForTelemetry].add(1);
